/**
 * 导航右上角：未登录链到控制台；已登录展示账户 policy launcher（不含组织 —— 组织在 console 公开页 /account）。
 *
 * @author 恒哥
 */
import React, {
  useEffect, useRef, useState,
} from 'react';
import { useAuth } from '../../auth/AuthProvider';
import {
  IDP_ACCOUNT_POLICIES,
  MESSAGING_CONSOLE_URL,
  SITE_URL,
} from '../../constants/brand';
import './nav-auth.css';

export default function NavAuth() {
  const {
    isAuthenticating, isAuthenticated, authenticationError,
    account, loginRedirect, logoutRedirect,
  } = useAuth();
  const [open, setOpen] = useState(false);
  const wrapRef = useRef(null);

  useEffect(() => {
    if (!open) return undefined;

    const onPointerDown = (event) => {
      if (wrapRef.current && !wrapRef.current.contains(event.target)) setOpen(false);
    };
    const onKeyDown = (event) => {
      if (event.key === 'Escape') setOpen(false);
    };

    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open]);

  if (isAuthenticating) {
    return <span className="nav-auth-placeholder" aria-hidden="true" />;
  }

  if (!isAuthenticated) {
    return (
      <a
        className="nav-auth-signin"
        href={`${MESSAGING_CONSOLE_URL}/`}
        title={authenticationError ?? undefined}
      >
        Console
      </a>
    );
  }

  const triggerLabel = account?.navLabel ?? account?.name ?? account?.email ?? '';
  const isTeam = account?.orgType === 'organization';
  const triggerTitle = [
    isTeam && account?.orgSlug ? `${account.orgName ?? account.orgSlug} (${account.orgSlug})` : null,
    !isTeam && account?.email ? account.email : null,
    isTeam && account?.email ? account.email : null,
  ].filter(Boolean).join(' · ');

  const handlePolicy = (policy) => {
    setOpen(false);
    loginRedirect({ policy });
  };

  const handleSignOut = () => {
    setOpen(false);
    logoutRedirect({ postLogoutRedirectUri: SITE_URL });
  };

  const renderPolicyItem = (item) => (
    <button
      key={item.policy}
      type="button"
      role="menuitem"
      className="nav-auth-item"
      onClick={() => handlePolicy(item.policy)}
    >
      {item.label}
    </button>
  );

  return (
    <div className="nav-auth" ref={wrapRef}>
      <button
        type="button"
        className="nav-auth-trigger"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
      >
        <span className="nav-auth-email" title={triggerTitle || undefined}>{triggerLabel}</span>
        <span className="nav-auth-caret" aria-hidden="true" />
      </button>

      {open ? (
        <div className="nav-auth-menu" role="menu">
          <a
            className="nav-auth-item nav-auth-item-link"
            role="menuitem"
            href={`${MESSAGING_CONSOLE_URL}/account`}
          >
            Organizations
          </a>
          <a
            className="nav-auth-item nav-auth-item-link"
            role="menuitem"
            href={`${MESSAGING_CONSOLE_URL}/`}
          >
            Console
          </a>
          <span className="nav-auth-separator" role="separator" />
          {IDP_ACCOUNT_POLICIES.map(renderPolicyItem)}
          <span className="nav-auth-separator" role="separator" />
          <button
            type="button"
            role="menuitem"
            className="nav-auth-item nav-auth-item-signout"
            onClick={handleSignOut}
          >
            Sign out
          </button>
        </div>
      ) : null}
    </div>
  );
}
