/**
 * 分析同意条
 *
 * 为什么必须有：官网面向欧洲商家（GDPR），且已有 /gdpr/ 与 /privacy/ 页面。
 * 之前全站零 cookie 零分析，所以不需要；一旦引入 GA4，
 * 按 ePrivacy/GDPR 必须在存非必要 cookie 前取得同意。
 *
 * 设计取舍：
 * - **Accept / Decline 两个等重按钮**，不预勾选、不用「继续即同意」——
 *   预勾选在欧盟监管口径下是明确不合规的。
 * - 选择存 localStorage，用户拒绝后不再弹（但仍可在 /privacy/ 撤回）。
 * - 纯客户端渲染（判断 localStorage 只能放 useEffect），SSR 时不渲染，避免闪烁。
 *
 * @author 恒哥
 */
import React, { useEffect, useState } from 'react';
import { Link } from 'gatsby';
import { getConsent, setConsent, trackEvent } from '../../utils/analytics';
import { useI18n } from '../../i18n';
import './analytics-consent.css';

export default function AnalyticsConsent() {
  const [visible, setVisible] = useState(false);
  // 🔴 2026-11-12：此前恒为英文。本组件挂在 Layout 的 I18nProvider 内，可直接读字典。
  const { t, localePath } = useI18n();
  const c = t.cookie;

  useEffect(() => {
    // 未配置 GA ID 时不打扰用户
    if (!process.env.GATSBY_GA_MEASUREMENT_ID) return;
    if (getConsent()) return;
    setVisible(true);
  }, []);

  const decide = (decision) => {
    setConsent(decision);
    if (decision === 'granted') {
      trackEvent('consent_granted');
    }
    setVisible(false);
  };

  if (!visible) return null;

  return (
    <div className="analytics-consent" role="region" aria-label={c.ariaLabel}>
      <div className="analytics-consent-text">
        <p className="analytics-consent-title">{c.title}</p>
        <p className="analytics-consent-body">
          {c.bodyPrefix}
          <Link to={localePath('/privacy/')}>{c.privacy}</Link>{c.suffix}
        </p>
      </div>
      <div className="analytics-consent-actions">
        <button
          type="button"
          className="analytics-consent-btn analytics-consent-btn-accept"
          onClick={() => decide('granted')}
        >
          {c.accept}
        </button>
        <button
          type="button"
          className="analytics-consent-btn analytics-consent-btn-decline"
          onClick={() => decide('denied')}
        >
          {c.decline}
        </button>
      </div>
    </div>
  );
}
