/**
 * 语言上下文：让组件读到当前语言与字典。
 *
 * 🔴 SSR 安全：优先用 `pageContext.locale`，路径推导只作兜底（Gatsby 5 两端都有），
 *    **不读 window/localStorage** —— 与 AuthProvider 同样的纪律，避免 hydration 不匹配。
 *
 * @author 恒哥
 */
import React, { createContext, useContext, useMemo } from 'react';
import { useLocation } from '@reach/router';
import { DEFAULT_LOCALE, LOCALES, getDictionary, localePath, resolveLocale } from './config';
import common from './dictionaries/common';
import pages from './dictionaries/pages';

const I18nContext = createContext({
  locale: DEFAULT_LOCALE,
  htmlLang: 'en',
  ogLocale: 'en_US',
  prefix: '',
  t: common[DEFAULT_LOCALE],
  page: pages[DEFAULT_LOCALE],
  localePath: (p) => p,
});

/** 取当前语言、字典与路径工具 */
export function useI18n() {
  return useContext(I18nContext);
}

/**
 * 提供语言上下文。挂在 Layout 内层即可（Layout 自己不消费，故放在子组件里）。
 *
 * 🔴 **SSR 关键**：优先用 Gatsby 传入的 `pageContext.locale`。
 *    ⚠️ 旧注释断言「SSR 阶段 `useLocation()` 恒返回 `/`」**已被 11-10 产物实测证伪**：
 *    Gatsby 5 的 SSR 返回真实路径，30 个本地化页的 150 条切换链接全部保持当前页。
 *    这里仍以 `pageContext.locale` 为准，是为了不依赖路由实现细节，而不是因为路径推导会错。
 *    判据：源码注释里的 SSR 断言不能当判据，必须抓静态 HTML。
 *    `locale` 由 gatsby-node.js 的 onCreatePage 注入（英文页为 undefined ⇒ 回落 en）。
 *    pathname 仅作浏览器端的兜底（不依赖 pageContext 的场景）。
 *
 * @param {{children: React.ReactNode, pathname: string, locale?: string}} props
 */
export function I18nProvider({ children, pathname, locale: localeProp }) {
  const location = useLocation();
  const clientPathname = pathname || (location && location.pathname) || '/';
  const value = useMemo(() => {
    const fromPath = resolveLocale(clientPathname);
    // pageContext.locale 优先（SSR 正确性）；缺失时回退按路径判断
    const locale =
      localeProp && LOCALES[localeProp] ? localeProp : fromPath.locale;
    const basePath = fromPath.basePath;
    const cfg = LOCALES[locale] || LOCALES[DEFAULT_LOCALE];
    return {
      locale,
      htmlLang: cfg.htmlLang,
      ogLocale: cfg.ogLocale,
      prefix: cfg.prefix,
      /** 当前页在各语言下的路径，用于 hreflang 与语言切换 */
      basePath,
      t: getDictionary(locale, common),
      page: getDictionary(locale, pages),
      localePath: (p) => localePath(p, locale),
    };
  }, [clientPathname, localeProp]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

/**
 * 页面组件专用：直接读 Gatsby 传入的 `pageContext.locale`。
 *
 * 🔴 **页面组件必须用这个，不要用 {@link useI18n}**（2026-10-08 实际踩到）。
 *    页面组件是 `<Layout>` 的**调用方**，即它在 `I18nProvider` **之外**渲染 ——
 *    而 Provider 只能影响它的后代。于是：
 *      页面 `useI18n()` → 拿到 context 默认值 **en** ⇒ 正文/SEO/链接全英文；
 *      Layout 内部（导航、页脚）→ 拿到 **de** ⇒ 同一页出现「导航德语、正文英语」。
 *    该 bug 不报错、构建成功、浏览器里也「正常」（hydrate 后会变），
 *    只有抓静态 HTML 才发现 ⇒ 对 SEO 是致命的，且极难自查。
 *
 *    `pageContext.locale` 由 gatsby-node.js 的 onCreatePage 在生成 `/de/*`、`/fr/*`
 *    时写入，是**唯一在 SSR 与客户端都正确**的来源。
 *
 * @param {object} [pageContext] Gatsby 传入的 pageContext
 * @returns {{locale: string, htmlLang: string, ogLocale: string, prefix: string,
 *            basePath: string, t: object, page: object,
 *            localePath: (p: string) => string}}
 */
export function usePageI18n(pageContext) {
  const location = useLocation();
  const pathname = (location && location.pathname) || '/';
  const fromPath = resolveLocale(pathname);
  const locale =
    pageContext && pageContext.locale && LOCALES[pageContext.locale]
      ? pageContext.locale
      : fromPath.locale;
  const cfg = LOCALES[locale] || LOCALES[DEFAULT_LOCALE];
  return {
    locale,
    htmlLang: cfg.htmlLang,
    ogLocale: cfg.ogLocale,
    prefix: cfg.prefix,
    basePath: fromPath.basePath,
    t: getDictionary(locale, common),
    page: getDictionary(locale, pages),
    localePath: (p) => localePath(p, locale),
  };
}

/**
 * 语言切换器用的路径数组。
 * @param {string} basePath 英文视角的当前页路径
 * @returns {Array<{code: string, label: string, to: string, isCurrent: boolean}>}
 */
export function useLocaleLinks(basePath) {
  const location = useLocation();
  const { locale: current } = resolveLocale(location.pathname || basePath || '/');
  return useMemo(
    () =>
      Object.keys(LOCALES).map((code) => ({
        code,
        label: LOCALES[code].nativeName,
        to: localePath(basePath || '/', code),
        isCurrent: code === current,
      })),
    [basePath, current]
  );
}
