/**
 * 语言切换器（2026-11-10 随中文落地新增；此前只有 `useLocaleLinks` 从未被渲染）
 *
 * 🔴 **遍历 `LOCALES`，绝不硬编码语言**：后续加到五种语言时，本组件零改动，
 *    菜单自动多出条目。用 `<details>` 收起态而不是平铺按钮，是因为导航条有
 *    硬宽度预算（logo + 6 链接 + 2 按钮，见 navigation.css 顶部算式），
 *    五种语言若平铺会直接把 1024–1400px 区间挤换行。
 *
 * 🔴 **未本地化页不加前缀**：`LOCALIZED_PAGES` 之外的页面（2026-11-12 起只剩
 *    privacy / terms / gdpr 法务长文、cart-rescue 兼容桩与数据驱动的族子页）只有英文版，
 *    切到中文会落到 `/zh/`（中文首页），
 *    绝不生成 `/zh/about/` 这种不存在的路由（历史上产生过 5 条死链）。
 *
 * ⚠️ **旧注释已被产物实测证伪**：`useLocation()` 在 Gatsby 5 的构建期返回真实路径，
 *    静态 HTML 里的切换链接 150/150 保持当前页（见 11-10 出证）。不再声称「恒返回 /」。
 *    链接始终有效（不会 404）。关键 SEO 信号 hreflang / canonical 由 `SEO` 组件
 *    用页面传入的 `pathname` 计算，不走这里。
 */
import React from 'react';
import { Link } from 'gatsby';
import { useLocation } from '@reach/router';
import { useI18n } from '../../i18n';
import {
  DEFAULT_LOCALE,
  LOCALES,
  isLocalizedPath,
  localePath,
  resolveLocale,
} from '../../i18n/config';
import './language-switcher.css';

export default function LanguageSwitcher() {
  const { pathname } = useLocation();
  const { locale, t } = useI18n();
  const { basePath } = resolveLocale(pathname || '/');
  const localized = isLocalizedPath(basePath);
  const others = Object.keys(LOCALES).filter((code) => code !== locale);

  if (others.length === 0) return null;

  const current = LOCALES[locale] || LOCALES[DEFAULT_LOCALE];
  return (
    <details className="lang-switcher">
      <summary aria-label={t.language.label} title={current.nativeName}>
        {current.shortLabel}
      </summary>
      <div className="lang-switcher-menu">
        {others.map((code) => {
          const cfg = LOCALES[code];
          // 已本地化 → 当前页的对应语言版本；未本地化 → 该语言首页
          const to = localized
            ? localePath(basePath, code)
            : code === DEFAULT_LOCALE
              ? '/'
              : `${cfg.prefix}/`;
          return (
            <Link
              key={code}
              to={to}
              className="lang-switcher-link"
              lang={cfg.htmlLang}
              title={cfg.nativeName}
            >
              {cfg.nativeName}
            </Link>
          );
        })}
      </div>
    </details>
  );
}
