/**
 * 渲染树文案层（2026-11-12，配合 dataCopy.js）
 *
 * 一处接入、全站生效：在 `Layout` 的壳层里对整棵 React 元素树做一次映射，
 * 把命中的英文字符串换成 zh / fr 译文。覆盖
 *   · 页面 children（含 data/*.js 卡片文案、<T> 的插槽节点、SEO 组件属性）
 *   · 页脚（COMPANY_DESCRIPTION、ECOSYSTEM_GROUPS[].items[].desc、Privacy/Terms）
 * 因此 20 个本地化页**一个都不用改**。
 *
 * 🔴 为什么可以安全地遍历 props：dc() 未命中即原样返回。早期字典只有「整句英文」，
 *    slug / className / to / href / id 天然不会命中；补进 145 条短标签后（如
 *    `Platform` / `Company` / `Support` 等 150 条短标签），"不会撞名" 不再是前提，因此这里改成
 *    **按属性名显式跳过结构类属性**，只保留文案类属性参与替换。
 *
 * 🔴 为什么不用 React.Children.toArray()：它会展开 `{items.map(...)}` 并重新编号
 *    key，导致 LocalizedText 的 `{0}` `{1}` 插槽错位（见该文件头部说明）。
 *    这里只用 Array.prototype.map 保形映射，数组长度与顺序完全不变。
 *
 * 🔴 SSR / hydration 一致：locale 来自 pageContext.locale（Layout 的 prop），
 *    SSR 与客户端取到同一个值；映射是纯函数，不读 window / Date / 随机数。
 *    en / de / es / ja 直接短路返回原节点，零行为变化、零额外开销。
 *
 * @author 恒哥
 */
import React from 'react';
import { dc, hasDataCopy } from './dataCopy';

/**
 * 这些属性绝不递归、绝不改写 —— 注入的 HTML、框架内部字段、以及所有
 * 「结构性」属性。短文案 key 加入后，`id="Platform"` / `to="Company"` 之类
 * 一旦被译文替换就会破坏锚点、路由与样式，属于静默故障，必须整支跳过。
 *（aria-label / alt / title / placeholder 等文案属性不在此列，照常翻译。）
 */
const SKIP_PROPS = new Set([
  'dangerouslySetInnerHTML', 'ref', 'key',
  'id', 'className', 'class', 'style',
  'to', 'href', 'src', 'srcSet', 'sizes', 'action', 'method', 'target', 'rel',
  'type', 'name', 'htmlFor', 'autoComplete', 'itemScope', 'itemType', 'itemProp',
  'property', 'charSet', 'httpEquiv', 'content',
  'width', 'height', 'viewBox', 'xmlns', 'lang', 'dir',
]);
const MAX_DEPTH = 60;

function isPlainObject(value) {
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function walkElement(el, locale, cache, depth) {
  const props = el.props || {};
  const next = {};
  for (const [name, value] of Object.entries(props)) {
    if (name === 'children' || SKIP_PROPS.has(name)) {
      next[name] = value;
      continue;
    }
    next[name] = walk(value, locale, cache, depth + 1);
  }
  // children 单独处理：必须保形，且通过 cloneElement 的第 3+ 个参数写回，
  // 否则 React 会沿用元素上的旧 children，译文根本不生效。
  delete next.children;

  if (props.children === undefined) return React.cloneElement(el, next);
  let kids = walk(props.children, locale, cache, depth + 1);

  // JSX 里一句话可能被切成多段文本节点（`{' '}`、换行、内联表达式边界）。
  // 全是纯字符串时先拼起来查一次字典，命中再合并成一个节点。
  if (Array.isArray(kids) && kids.length > 1 && kids.every((c) => typeof c === 'string')) {
    const joined = kids.join('');
    const translated = dc(joined, locale);
    if (translated !== joined) kids = [translated];
  }

  return Array.isArray(kids)
    ? React.cloneElement(el, next, ...kids)
    : React.cloneElement(el, next, kids);
}

function walk(node, locale, cache, depth) {
  if (typeof node === 'string') return dc(node, locale);
  if (node === null || node === undefined) return node;
  if (typeof node !== 'object') return node; // number / boolean / function / symbol
  if (depth > MAX_DEPTH) return node;
  if (cache.has(node)) return cache.get(node);

  let out;
  if (Array.isArray(node)) {
    out = node.map((child) => walk(child, locale, cache, depth + 1));
  } else if (React.isValidElement(node)) {
    out = walkElement(node, locale, cache, depth);
  } else if (isPlainObject(node)) {
    out = {};
    for (const [name, value] of Object.entries(node)) {
      out[name] = SKIP_PROPS.has(name) ? value : walk(value, locale, cache, depth + 1);
    }
  } else {
    out = node; // Date / Map / 类实例等，保持引用
  }
  cache.set(node, out); // 同一节点在树里复用时保持身份一致
  return out;
}

/**
 * @param {React.ReactNode} node 待处理的 React 树
 * @param {string} locale 当前语言
 * @returns {React.ReactNode} 译文替换后的树；无该语言字典时原样返回
 */
export default function localizeReact(node, locale) {
  if (!hasDataCopy(locale)) return node;
  return walk(node, locale, new Map(), 0);
}
